import{_ as l,a0 as o,w as d,s as r,I as n,x as a,a1 as e,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Ohm：用兩百行 JavaScript 創造你自己的編程語言 | LCTT x X-CMD","titleTemplate":false,"description":"Ohm：用兩百行 JavaScript 創造你自己的編程語言 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ohm：用兩百行 JavaScript 創造你自己的編程語言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ohm：用兩百行 JavaScript 創造你自己的編程語言 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160830 Ohm JavaScript Parser that Create a Language in 200 Lines of Code","title":"Ohm：用兩百行 JavaScript 創造你自己的編程語言","tag":"201609","desc":""},"relativePath":"201609/20160830 Ohm JavaScript Parser that Create a Language in 200 Lines of Code.md","filePath":"[post].md"}'),g={name:"201609/20160830 Ohm JavaScript Parser that Create a Language in 200 Lines of Code.md"};function u(c,s,h,k,b,m){const i=o("Link");return d(),r("div",null,[s[42]||(s[42]=n("h1",{id:"ohm-用兩百行-javascript-創造你自己的編程語言",tabindex:"-1"},[a("Ohm：用兩百行 JavaScript 創造你自己的編程語言 "),n("a",{class:"header-anchor",href:"#ohm-用兩百行-javascript-創造你自己的編程語言","aria-label":"Permalink to “Ohm：用兩百行 JavaScript 創造你自己的編程語言”"},"​")],-1)),s[43]||(s[43]=n("p",null,[n("img",{src:"https://www.pubnub.com/wp-content/uploads/2016/08/ohm-banner.jpg",alt:""})],-1)),s[44]||(s[44]=n("p",null,"解析器是一種超級有用的軟件庫。從概念上簡單的説，它們的實現很有挑戰性，並且在計算機科學中經常被認為是黑魔法。在這個系列的博文中，我會向你們展示為什麼你不需要成為哈利波特就能夠精通解析器這種魔法。但是為了以防萬一帶上你的魔杖吧！",-1)),s[45]||(s[45]=n("p",null,"我們將探索一種叫做 Ohm 的新的開源庫，它使得搭建解析器很簡單並且易於重用。在這個系列裏，我們使用 Ohm 去識別數字，構建一個計算器等等。在這個系列的最後你將已經用不到 200 行的代碼發明了一種完整的編程語言。這個強大的工具將讓你能夠做到一些你可能過去認為不可能的事情。",-1)),s[46]||(s[46]=n("p",null,"###為什麼解析器很困難？",-1)),s[47]||(s[47]=n("p",null,"解析器非常有用。在很多時候你可能需要一個解析器。或許有一種你需要處理的新的文件格式，但還沒有人為它寫了一個庫；又或許你發現了一種古老格式的文件，但是已有的解析器不能在你的平台上構建。我已經看到這樣的事發生無數次。 Code 在或者不在， Data 就在那裏，不增不減。",-1)),s[48]||(s[48]=n("p",null,"從根本上來説，解析器很簡單：只是把一個數據結構轉化成另一個。所以你會不會覺得你要是鄧布利多校長就好了？",-1)),s[49]||(s[49]=n("p",null,"解析器歷來是出奇地難寫，所面臨的挑戰是絕大多數現有的工具都很老，並且需要一定的晦澀難懂的計算機科學知識。如果你在大學裏上過編譯器課程，那麼課本里也許還有從上世紀七十年傳下來的技術。幸運的是，解析器技術從那時候起已經提高了很多。",-1)),n("p",null,[s[3]||(s[3]=a("典型的，解析器是通過使用一種叫作",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Formal_grammar"},{default:t(()=>[...s[0]||(s[0]=[a("形式語法（formal grammar）",-1)])]),_:1}),s[4]||(s[4]=a("的特殊語法來定義你想要解析的東西來創造的，然後你需要把它放入像 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/GNU_bison"},{default:t(()=>[...s[1]||(s[1]=[a("Bison",-1)])]),_:1}),s[5]||(s[5]=a(" 和 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Yacc"},{default:t(()=>[...s[2]||(s[2]=[a("Yacc",-1)])]),_:1}),s[6]||(s[6]=a(" 的工具中，這些工具能夠產生一堆 C 代碼，這些代碼你需要修改或者鏈接到你實際寫入的編程語言中。另外的選擇是用你更喜歡的語言親自動手寫一個解析器，這很慢且很容易出錯，在你能夠真正使用它之前還有許多額外的工作。",-1))]),s[50]||(s[50]=n("p",null,"想像一下，是否你關於你想要解析的東西的語法描述也是解析器？如果你能夠只是直接運行這些語法，然後僅在你需要的地方增加一些掛鈎（hook）呢？那就是 Ohm 所可以做到的事。",-1)),s[51]||(s[51]=n("h3",{id:"ohm-簡介",tabindex:"-1"},[a("Ohm 簡介 "),n("a",{class:"header-anchor",href:"#ohm-簡介","aria-label":"Permalink to “Ohm 簡介”"},"​")],-1)),n("p",null,[e(i,{href:"https://github.com/cdglabs/ohm"},{default:t(()=>[...s[7]||(s[7]=[a("Ohm",-1)])]),_:1}),s[8]||(s[8]=a("是一種新的解析系統。它類似於你可能已經在課本里面看到過的語法，但是它更強大，使用起來更簡單。通過 Ohm, 你能夠使用一種靈活的語法在一個 .ohm 文件中來寫你自己的格式定義，然後使用你的宿主語言把語義加入到裏面。在這篇博文裏，我們將用 JavaScript 作為宿主語言。",-1))]),n("p",null,[s[11]||(s[11]=a("Ohm 建立於一個為創造更簡單、更靈活的解析器的多年研究基礎之上。VPRI 的 ",-1)),e(i,{href:"http://www.vpri.org/pdf/tr2012001_steps.pdf"},{default:t(()=>[...s[9]||(s[9]=[a("STEPS program (pdf)",-1)])]),_:1}),s[12]||(s[12]=a(" 使用 Ohm 的前身 ",-1)),e(i,{href:"http://tinlizzie.org/ometa/"},{default:t(()=>[...s[10]||(s[10]=[a("Ometa",-1)])]),_:1}),s[13]||(s[13]=a(" 為許多特殊的任務創造了專門的語言（比如一個有 400 行代碼的平行製圖描繪器）。",-1))]),s[52]||(s[52]=p(`<p>Ohm 有許多有趣的特點和符號，但是相比於全部解釋它們，我認為我們只需要深入其中並構建一些東西就行了。</p><p>###解析整數</p><p>讓我們來解析一些數字。這看起來會很簡單，只需在一個文本串中尋找毗鄰的數字，但是讓我們嘗試去處理所有形式的數字：整數和浮點數、十六進制數和八進制數、科學計數、負數。解析數字很簡單，正確解析卻很難。</p><p>親自構建這個代碼將會很困難，會有很多問題，會伴隨有許多特殊的情況，比如有時會相互矛盾。正則表達式或許可以做的這一點，但是它會非常醜陋而難以維護。讓我們用 Ohm 來試試。</p><p>用 Ohm 構建的解析器涉及三個部分：語法（grammar）、語義（semantics）和測試（tests）。我通常挑選問題的一部分為它寫測試，然後構建足夠的語法和語義來使測試通過。然後我再挑選問題的另一部分，增加更多的測試、更新語法和語義，從而確保所有的測試能夠繼續通過。即使我們有了新的強大的工具，寫解析器從概念上來説依舊很複雜。測試是用一種合理的方式來構建解析器的唯一方法。現在，讓我們開始工作。</p><p>我們將從整數開始。一個整數由一系列相互毗鄰的數字組成。讓我們把下面的內容放入一個叫做 grammar.ohm 的文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CoolNums {</span></span>
<span class="line"><span>   // just a basic integer</span></span>
<span class="line"><span>   Number = digit+</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這創造了一條匹配一個或多個數字（<code>digit</code>）叫作 <code>Number</code> 的單一規則。<code>＋</code> 意味着一個或更多，就在正則表達式中一樣。當有一個或更多的數字時，這個規則將會匹配它們，如果沒有數字或者有一些不是數字的東西將不會匹配。“數字（<code>digit</code>）”的定義是從 0 到 9 其中的一個字符。<code>digit</code> 也是像 <code>Number</code> 一樣的規則，但是它是 Ohm 的其中一條構建規則因此我們不需要去定義它。如果我們想的話可以推翻它，但在這時候這沒有任何意義，畢竟我們不打算去發明一種新的數。</p><p>現在，我們可以讀入這個語法並用 Ohm 庫來運行它。</p><p>把它放入 test1.js：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var ohm = require(&#39;ohm-js&#39;);</span></span>
<span class="line"><span>var fs = require(&#39;fs&#39;);</span></span>
<span class="line"><span>var assert = require(&#39;assert&#39;);</span></span>
<span class="line"><span>var grammar = ohm.grammar(fs.readFileSync(&#39;src/blog_numbers/syntax1.ohm&#39;).toString());</span></span></code></pre></div><p><code>Ohm.grammar</code> 調用將讀入該文件並解析成一個語法對象。現在我們可以增加一些語義。把下面內容增加到你的 JavaScript 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var sem = grammar.createSemantics().addOperation(&#39;toJS&#39;, {</span></span>
<span class="line"><span>    Number: function(a) {</span></span>
<span class="line"><span>        return parseInt(this.sourceString,10);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>這通過 <code>toJS</code> 操作創造了一個叫作 <code>sem</code> 的語法集。這些語義本質上是一些對應到語法中每個規則的函數。每個函數當與之相匹配的語法規則被解析時將會被調用。上面的 <code>Number</code> 函數將會在語法中的 <code>Number</code> 規則被解析時被調用。語法（grammar）定義了在語言中這些代碼是什麼，語義（semantics）定義了當這些代碼被解析時應該做什麼。</p><p>語義函數能夠做我們想做的任何事，比如打印出故障信息、創建對象，或者在任何子節點上遞歸調用 <code>toJS</code>。此時我們僅僅想把匹配的文本轉換成真正的 JavaScript 整數。</p><p>所有的語義函數有一個內含的 <code>this</code> 對象，帶有一些有用的屬性。其 <code>source</code> 屬性代表了輸入文本中和這個節點相匹配的部分。<code>this.sourceString</code> 是一個匹配輸入的串，調用內置在 JavaScript 中的 <code>parseInt</code> 函數會把這個串轉換成一個數。傳給 <code>parseInt</code> 的 <code>10</code> 這個參數告訴 JavaScript 我們輸入的是一個以 <code>10</code> 為基底（10 進制）的數。如果少了這個參數， JavaScript 也會假定以 10 為基底，但是我們把它包含在裏面因為後面我們將支持以 16 為基底的數，所以使之明確比較好。</p><p>既然我們有一些語法，讓我們來實際解析一些東西看一看我們的解析器是否能夠工作。如何知道我們的解析器可以工作？通過測試，許多許多的測試，每一個可能的邊緣情況都需要一個測試。</p><p>使用標準的斷言 <code>assert</code> API，以下這個測試函數能夠匹配一些輸入並運用我們的語義把它轉換成一個數，然後把這個數和我們期望的輸入進行比較。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   function test(input, answer) {</span></span>
<span class="line"><span>     var match = grammar.match(input);</span></span>
<span class="line"><span>     if(match.failed()) return console.log(&quot;input failed to match &quot; + input + match.message);     </span></span>
<span class="line"><span>     var result = sem(match).toJS();</span></span>
<span class="line"><span>     assert.deepEqual(result,answer);</span></span>
<span class="line"><span>     console.log(&#39;success = &#39;, result, answer);</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>就是如此。現在我們能夠為各種不同的數寫一堆測試。如果匹配失敗我們的腳本將會拋出一個例外。否則就打印成功信息。讓我們嘗試一下，把下面這些內容加入到腳本中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    test(&quot;123&quot;,123);</span></span>
<span class="line"><span>    test(&quot;999&quot;,999);</span></span>
<span class="line"><span>    test(&quot;abc&quot;,999);</span></span></code></pre></div><p>然後用 <code>node test1.js</code> 運行腳本。</p><p>你的輸出應該是這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>success =  123 123</span></span>
<span class="line"><span>success =  999 999</span></span>
<span class="line"><span>input failed to match abcLine 1, col 1:</span></span>
<span class="line"><span>&gt; 1 | abc</span></span>
<span class="line"><span>      ^</span></span>
<span class="line"><span>Expected a digit</span></span></code></pre></div><p>真酷。正如預期的那樣，前兩個成功了，第三個失敗了。更好的是，Ohm 自動給了我們一個很棒的錯誤信息指出匹配失敗。</p><p>###浮點數</p><p>我們的解析器工作了，但是它做的工作不是很有趣。讓我們把它擴展成既能解析整數又能解析浮點數。改變 grammar.ohm 文件使它看起來像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CoolNums {</span></span>
<span class="line"><span>  // just a basic integer</span></span>
<span class="line"><span>  Number = float | int</span></span>
<span class="line"><span>  int    = digit+</span></span>
<span class="line"><span>  float  = digit+ &quot;.&quot; digit+</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這把 <code>Number</code> 規則改變成指向一個浮點數（<code>float</code>）或者一個整數（<code>int</code>）。這個 <code>|</code> 代表着“或”。我們把這個讀成“一個 <code>Number</code> 由一個浮點數或者一個整數構成。”然後整數（<code>int</code>）定義成 <code>digit+</code>，浮點數（<code>float</code>）定義成 <code>digit+</code> 後面跟着一個句號然後再跟着另一個 <code>digit+</code>。這意味着在句號前和句號後都至少要有一個數字。如果一個數中沒有一個句號那麼它就不是一個浮點數，因此就是一個整數。</p><p>現在，讓我們再次看一下我們的語義功能。由於我們現在有了新的規則所以我們需要新的功能函數：一個作為整數的，一個作為浮點數的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var sem = grammar.createSemantics().addOperation(&#39;toJS&#39;, {</span></span>
<span class="line"><span>    Number: function(a) {</span></span>
<span class="line"><span>        return a.toJS();</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    int: function(a) {</span></span>
<span class="line"><span>        console.log(&quot;doing int&quot;, this.sourceString);</span></span>
<span class="line"><span>        return parseInt(this.sourceString,10);</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    float: function(a,b,c) {</span></span>
<span class="line"><span>        console.log(&quot;doing float&quot;, this.sourceString);</span></span>
<span class="line"><span>        return parseFloat(this.sourceString);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>這裏有兩件事情需要注意。首先，整數（<code>int</code>）、浮點數（<code>float</code>）和數（<code>Number</code>）都有相匹配的語法規則和函數。然而，針對 <code>Number</code> 的功能不再有任何意義。它接收子節點 <code>a</code> 然後返回該子節點的 <code>toJS</code> 結果。換句話説，<code>Number</code> 規則簡單的返回相匹配的子規則。由於這是在 Ohm 中任何規則的默認行為，因此實際上我們不用去考慮 <code>Number</code> 的作用，Ohm 會替我們做好這件事。</p>`,32)),n("p",null,[s[15]||(s[15]=a("其次，整數（",-1)),s[16]||(s[16]=n("code",null,"int",-1)),s[17]||(s[17]=a("）有一個參數 ",-1)),s[18]||(s[18]=n("code",null,"a",-1)),s[19]||(s[19]=a("，然而浮點數有三個：",-1)),s[20]||(s[20]=n("code",null,"a",-1)),s[21]||(s[21]=a("、",-1)),s[22]||(s[22]=n("code",null,"b",-1)),s[23]||(s[23]=a(" 和 ",-1)),s[24]||(s[24]=n("code",null,"c",-1)),s[25]||(s[25]=a("。這是由於規則的實參數量（arity）決定的。",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Arity"},{default:t(()=>[...s[14]||(s[14]=[a("實參數量（arity）",-1)])]),_:1}),s[26]||(s[26]=a(" 意味着一個規則裏面有多少參數。如果我們回過頭去看語法，浮點數（",-1)),s[27]||(s[27]=n("code",null,"float",-1)),s[28]||(s[28]=a("）的規則是：",-1))]),s[53]||(s[53]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  float  = digit+ &quot;.&quot; digit+</span></span></code></pre></div><p>浮點數規則通過三個部分來定義：第一個 <code>digit+</code>、<code>.</code>、以及第二個 <code>digit+</code>。這三個部分都會作為參數傳遞給浮點數的功能函數。因此浮點數必須有三個參數，否則 Ohm 庫會給出一個錯誤。在這種情況下我們不用在意參數，因為我們僅僅直接攫取了輸入串，但是我們仍然需要參數列在那裏來避免編譯器錯誤。後面我們將實際使用其中一些參數。</p><p>現在我們可以為新的浮點數支持添加更多的測試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test(&quot;123&quot;,123);</span></span>
<span class="line"><span>test(&quot;999&quot;,999);</span></span>
<span class="line"><span>//test(&quot;abc&quot;,999);</span></span>
<span class="line"><span>test(&#39;123.456&#39;,123.456);</span></span>
<span class="line"><span>test(&#39;0.123&#39;,0.123);</span></span>
<span class="line"><span>test(&#39;.123&#39;,0.123);</span></span></code></pre></div><p>注意最後一個測試將會失敗。一個浮點數必須以一個數開始，即使它就是個 0，<code>.123</code> 不是有效的，實際上真正的 JavaScript 語言也有相同的規則。</p><p>###十六進制數</p><p>現在我們已經有了整數和浮點數，但是還有一些其它的數的語法最好可以支持：十六進制數和科學計數。十六進制數是以 16 為基底的整數。十六進制數的數字能從 0 到 9 和從 A 到 F。十六進制數經常用在計算機科學中，當用二進制數據工作時，你可以僅僅使用兩個數字表示 0 到 255 的數。</p><p>在絕大多數源自 C 的編程語言（包括 JavaScript），十六進制數通過在前面加上 <code>0x</code> 來向編譯器表明後面跟的是一個十六進制數。為了讓我們的解析器支持十六進制數，我們只需要添加另一條規則。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  Number = hex | float | int</span></span>
<span class="line"><span>  int    = digit+</span></span>
<span class="line"><span>  float  = digit+ &quot;.&quot; digit+</span></span>
<span class="line"><span>  hex    = &quot;0x&quot; hexDigit+</span></span>
<span class="line"><span>  hexDigit := &quot;0&quot;..&quot;9&quot; | &quot;a&quot;..&quot;f&quot; | &quot;A&quot;..&quot;F&quot;</span></span></code></pre></div><p>我實際上已經增加了兩條規則。十六進制數（<code>hex</code>）表明它是一個 <code>0x</code> 後面一個或多個十六進制數字（<code>hexDigits</code>）的串。一個十六進制數字（<code>hexDigit</code>）是從 0 到 9，或從 a 到 f，或 A 到 F（包括大寫和小寫的情況）的一個字符。我也修改了 <code>Number</code> 規則來識別十六進制數作為另外一種可能的情況。現在我們只需要另一條針對十六進制數的功能規則。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    hex: function(a,b) {</span></span>
<span class="line"><span>        return parseInt(this.sourceString,16);</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>注意到，在這種情況下，我們把 <code>16</code> 作為基底傳遞給 <code>parseInt</code>，因為我們希望 JavaScript 知道這是一個十六進制數。</p><p>我略過了一些很重要需要注意的事。<code>hexDigit</code> 的規則像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  hexDigit := &quot;0&quot;..&quot;9&quot; | &quot;a&quot;..&quot;f&quot; | &quot;A&quot;..&quot;F&quot;</span></span></code></pre></div><p>注意我使用的是 <code>:=</code> 而不是 <code>=</code>。在 Ohm 中，<code>:=</code> 是當你需要推翻一條規則的時候使用。這表明 Ohm 已經有了一條針對 <code>hexDigit</code> 的默認規則，就像 <code>digit</code>、<code>space</code> 等一堆其他的東西。如果我使用了 <code>=</code>, Ohm 將會報告一個錯誤。這是一個檢查，從而避免我無意識的推翻一個規則。由於新的 <code>hexDigit</code> 規則和 Ohm 的構建規則一樣，所以我們可以把它註釋掉，然後讓 Ohm 自己來實現它。我留下這個規則只是因為這樣我們可以看到它實際上是如何進行的。</p><p>現在，我們可以添加更多的測試然後看到十六進制數真的能工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test(&#39;0x456&#39;,0x456);</span></span>
<span class="line"><span>test(&#39;0xFF&#39;,255);</span></span></code></pre></div><p>###科學計數</p><p>最後，讓我們來支持科學計數。科學計數是針對非常大或非常小的數的，比如 <code>1.8×10^3</code>。在大多數編程語言中，科學計數法表示的數會寫成這樣：1.8e3 表示 18000，或者 1.8e-3 表示 .018。讓我們增加另外一對規則來支持這個指數表示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    float  = digit+ &quot;.&quot; digit+ exp?</span></span>
<span class="line"><span>    exp    = &quot;e&quot; &quot;-&quot;? digit+</span></span></code></pre></div><p>上面在浮點數規則末尾增加了一個指數（<code>exp</code>）規則和一個 <code>?</code>。<code>?</code> 表示沒有或有一個，所以指數（<code>exp</code>）是可選的，但是不能超過一個。增加指數（<code>exp</code>）規則也改變了浮點數規則的實參數量，所以我們需要為浮點數功能增加另一個參數，即使我們不使用它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    float: function(a,b,c,d) {</span></span>
<span class="line"><span>        console.log(&quot;doing float&quot;, this.sourceString);</span></span>
<span class="line"><span>        return parseFloat(this.sourceString);</span></span>
<span class="line"><span>    },</span></span></code></pre></div><p>現在我們的測試可以通過了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test(&#39;4.8e10&#39;,4.8e10);</span></span>
<span class="line"><span>test(&#39;4.8e-10&#39;,4.8e-10);</span></span></code></pre></div><p>###結論</p><p>Ohm 是構建解析器的一個很棒的工具，因為它易於上手，並且你可以遞增的增加規則。Ohm 也還有其他我今天沒有寫到的很棒的特點，比如調試觀察儀和子類化。</p><p>到目前為止，我們已經使用 Ohm 來把字符串翻譯成 JavaScript 數，並且 Ohm 經常用於把一種表示方式轉化成另外一種。然而，Ohm 還有更多的用途。通過放入不同的語義功能集，你可以使用 Ohm 來真正處理和計算東西。一個單獨的語法可以被許多不同的語義使用，這是 Ohm 的魔法之一。</p><p>在這個系列的下一篇文章中，我將向你們展示如何像真正的計算機一樣計算像 <code>(4.85 + 5 * (238 - 68)/2)</code> 這樣的數學表達式，不僅僅是解析數。</p><p>額外的挑戰：你能夠擴展語法來支持八進制數嗎？這些以 8 為基底的數能夠只用 0 到 7 這幾個數字來表示，前面加上一個數字 0 或者字母 <code>o</code>。看看針對下面這些測試情況是夠正確。下次我將給出答案。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test(&#39;0o77&#39;,7*8+7);</span></span>
<span class="line"><span>test(&#39;0o23&#39;,0o23);</span></span></code></pre></div><hr>`,31)),n("p",null,[s[30]||(s[30]=a("via: ",-1)),e(i,{href:"https://www.pubnub.com/blog/2016-08-30-javascript-parser-ohm-makes-creating-a-programming-language-easy/"},{default:t(()=>[...s[29]||(s[29]=[a("https://www.pubnub.com/blog/2016-08-30-javascript-parser-ohm-makes-creating-a-programming-language-easy/",-1)])]),_:1})]),n("p",null,[s[34]||(s[34]=a("作者：",-1)),e(i,{href:"https://www.pubnub.com/blog/author/josh/"},{default:t(()=>[...s[31]||(s[31]=[a("Josh Marinacci",-1)])]),_:1}),s[35]||(s[35]=a(" 譯者：",-1)),e(i,{href:"https://github.com/ucasFL"},{default:t(()=>[...s[32]||(s[32]=[a("ucasFL",-1)])]),_:1}),s[36]||(s[36]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[33]||(s[33]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[39]||(s[39]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[37]||(s[37]=[a("LCTT",-1)])]),_:1}),s[40]||(s[40]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[38]||(s[38]=[a("Linux中國",-1)])]),_:1}),s[41]||(s[41]=a(" 榮譽推出",-1))])])}const y=l(g,[["render",u]]);export{C as __pageData,y as default};
